import {cycle,dateKey,initial,rollover,metrics,spentFor,palette,amountCents,parseDay} from './core.js';
const demo=new URLSearchParams(location.search).has('demo'),KEY=demo?'daylight-demo-v1':'daylight-v1';let state,view='home',filter=null,storageError=false;const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
const euro=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n/100),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=s=>parseDay(s).toLocaleDateString('en-GB',{day:'numeric',month:'short'}),id=()=>crypto.randomUUID();
try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):initial();if(state.version!==1||!Array.isArray(state.categories)||!Array.isArray(state.entries))throw Error('Invalid saved data');if(demo&&!saved){const amounts=[11260,1840,6800,2150];state.entries=amounts.map((amount,i)=>({id:id(),categoryId:'c'+i,amount,time:new Date().toISOString()}))}rollover(state);localStorage.setItem(KEY,JSON.stringify(state))}catch(e){state=initial();storageError=true}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageError=false;return true}catch{storageError=true;render();return false}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',2600)}
function commit(s){persist();sheet.close();render();toast(storageError?'Changes cannot be saved on this browser. Keep the app open.':s)}
function active(){return state.categories.filter(c=>!c.archived)}
function summary(c){const cats=active();const budget=cats.reduce((s,x)=>s+x.budget,0);const spent=cats.reduce((s,x)=>s+spentFor(state,x.id),0);return metrics(budget,spent,c)}
function status(m){if(m.over)return 'Budget exceeded · '+euro(-m.remaining)+' over';if(m.noSpend===Infinity)return 'No budget set · spending recorded';return m.noSpend>0?`Spend nothing for ${m.noSpend} ${m.noSpend===1?'day':'days'} to get back on track`:'On track'}
function render(){const c=cycle(),m=summary(c);app.innerHTML=`<main class="container"><header><div><div class="brand"><span class="sun" aria-hidden="true"></span>daylight ${demo?'<span class="badge">DEMO</span>':''}</div><div class="sub">A little clarity between paydays.</div></div><nav class="nav" aria-label="Main"><button class="plain ${view==='home'?'active':''}" data-view="home">Today</button><button class="plain ${view==='settings'?'active':''}" data-view="settings">Manage</button></nav></header>${storageError?'<div class="notice" role="alert">Local saving is unavailable or saved data could not be read. Changes may be lost. Check browser storage before using this for your budget.</div>':''}${demo?'<div class="notice">You’re trying sample spending in a separate demo budget. <a href="./">Open your own budget →</a></div>':''}${view==='home'?home(c,m):view==='settings'?settings(c):history(c)}<footer class="footer">Your budget stays on this device. No accounts. No tracking.${!demo?' <a href="?demo">Try the demo</a>':''}</footer></main>${view==='home'?'<button class="add floating" data-action="add">＋ Add spending</button>':''}`;
app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;filter=null;render()});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));}
function home(c,m){return `<div class="eyebrow">YOUR EVERYDAY BUDGET</div><h1>Make room for today.</h1><section class="hero" aria-label="Overall budget"><div class="hero-main"><div><div class="eyebrow">AVAILABLE PER DAY</div><div class="big">${euro(m.daily)} <span class="per">/ day</span></div><div class="muted">${m.remaining<0?'Your active budgets are over by '+euro(-m.remaining):euro(m.remaining)+' left to enjoy this cycle'}</div></div><div class="cycle-pill"><strong>${c.remaining}</strong><span class="muted">spending days left</span></div></div><div class="hero-stats"><div><div class="stat-label">ORIGINAL BUDGET</div><div class="stat-value">${euro(m.budget)}</div></div><div><div class="stat-label">SPENT SO FAR</div><div class="stat-value">${euro(m.spent)}</div></div><div><div class="stat-label">REMAINING</div><div class="stat-value">${euro(m.remaining)}</div></div></div></section><div class="cycle-line"><span>Cycle began ${short(c.start)}</span><span>Next payday <strong>${short(c.next)}</strong></span></div><div class="section-head"><h2>Your categories</h2><button class="plain" data-action="history">History ↗</button></div><div class="cards">${active().map(cat=>{const a=metrics(cat.budget,spentFor(state,cat.id),c);return `<button class="category" style="--accent:${cat.color}" data-action="category" data-id="${cat.id}" aria-label="${esc(cat.name)} spending history"><div class="card-top"><span class="emoji">${esc(cat.emoji)}</span>${esc(cat.name)}</div><div class="card-daily ${a.over?'negative':''}">${euro(a.daily)} <small>/ day</small></div><div class="remaining"><strong>${euro(a.remaining)}</strong> remaining</div><div class="bar" role="progressbar" aria-label="Budget used" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,cat.budget?a.spent/cat.budget*100:0)}"><span style="width:${Math.min(100,cat.budget?a.spent/cat.budget*100:0)}%"></span></div><div class="card-meta"><span>${euro(a.spent)} spent of ${euro(cat.budget)}</span><span>${c.remaining} days left</span></div><div class="status ${a.noSpend>0||a.over?'warn':''}">${a.noSpend>0||a.over?'↗':'✓'} ${status(a)}</div></button>`}).join('')||'<div class="empty">Create a category in Manage to get started.</div>'}</div>`}
function settings(c){return `<div class="eyebrow">MAKE IT YOURS</div><h1>Manage your budget.</h1><div class="panel"><h2>Your payday rhythm</h2><p class="muted">Payday is the 15th. If it falls on a weekend, it moves back to Friday. Public holidays do not change this rule.</p><div class="row"><span>Current cycle</span><strong>${short(c.start)} – ${short(dateKey(new Date(parseDay(c.next).getFullYear(),parseDay(c.next).getMonth(),parseDay(c.next).getDate()-1)))}</strong></div><div class="row"><span>Next payday</span><strong>${short(c.next)}</strong></div><p class="muted">On payday, spending resets and your category budgets carry forward. Unspent money does not carry forward.</p></div><div class="section-head"><h2>Categories</h2><button class="add" data-action="new">＋ Add category</button></div><div class="panel">${state.categories.map(cat=>`<div class="row"><div class="row-name"><span class="emoji" style="--accent:${cat.color}">${esc(cat.emoji)}</span><div><strong>${esc(cat.name)}</strong><div class="muted">${euro(cat.budget)} per cycle ${cat.archived?'· Archived':''}</div></div></div><div class="actions">${!cat.archived?`<button class="small" aria-label="Move ${esc(cat.name)} up" data-action="up" data-id="${cat.id}">↑</button><button class="small" aria-label="Move ${esc(cat.name)} down" data-action="down" data-id="${cat.id}">↓</button>`:''}<button class="small" data-action="editcat" data-id="${cat.id}">Edit</button><button class="plain danger" data-action="${cat.archived?'restore':'archive'}" data-id="${cat.id}">${cat.archived?'Restore':'Archive'}</button></div></div>`).join('')||'<p class="muted">No categories yet.</p>'}</div><p class="muted">Archiving excludes a category and its spending from your active totals. Entries remain in history and return to totals if restored.</p>`}
function history(){const cat=state.categories.find(x=>x.id===filter),entries=state.entries.filter(e=>!filter||e.categoryId===filter).slice().sort((a,b)=>b.time.localeCompare(a.time));return `<button class="plain" data-view="home">← Today</button><div class="eyebrow">CURRENT CYCLE</div><h1>${cat?esc(cat.emoji)+' '+esc(cat.name):'Spending history'}</h1><div class="panel">${entries.map(e=>{const x=state.categories.find(x=>x.id===e.categoryId);const d=new Date(e.time);return `<div class="row"><div class="row-name"><span class="emoji" style="--accent:${x.color}">${esc(x.emoji)}</span><div><div class="history-money">${euro(e.amount)}</div><div class="history-date">${esc(x.name)}${x.archived?' · Archived':''}<br>${d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})} · ${d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</div></div></div><div class="actions"><button class="small" data-action="editentry" data-id="${e.id}">Edit</button><button class="plain danger" data-action="delete" data-id="${e.id}">Delete</button></div></div>`}).join('')||'<div class="empty"><h2>A fresh start.</h2><p class="muted">Your spending will appear here as you go.</p></div>'}</div><button class="add" data-action="add">＋ Add spending</button>`}
function modal(title,body){sheet.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="plain" id="close" aria-label="Close">✕</button></div>${body}`;sheet.querySelector('#close').onclick=()=>sheet.close();sheet.showModal()}
function expense(entry){const cats=state.categories.filter(c=>!c.archived||c.id===entry?.categoryId);let selected=entry?.categoryId||(filter&&cats.some(x=>x.id===filter)?filter:null);if(!cats.length){toast('Add a category in Manage first.');return}modal(entry?'Edit spending':'Add spending',`<form id="expense"><label for="amount">Amount in euros</label><input class="amount-input" id="amount" name="amount" type="text" inputmode="decimal" placeholder="0.00" autocomplete="off" required value="${entry?(entry.amount/100).toFixed(2):''}"><label>Choose a category</label><div class="choices">${cats.map(c=>`<button type="button" class="choice ${selected===c.id?'selected':''}" style="--accent:${c.color}" data-cat="${c.id}" aria-pressed="${selected===c.id}">${esc(c.emoji)} ${esc(c.name)}</button>`).join('')}</div><div class="error" role="alert"></div><button class="save">${entry?'Save changes':'Save spending'}</button></form>`);sheet.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{selected=b.dataset.cat;sheet.querySelectorAll('[data-cat]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})});sheet.querySelector('form').onsubmit=e=>{e.preventDefault();try{const amount=amountCents(sheet.querySelector('#amount').value);if(amount===0)throw Error('Enter an amount greater than zero.');if(!selected)throw Error('Choose a category.');if(entry){entry.amount=amount;entry.categoryId=selected}else state.entries.push({id:id(),amount,categoryId:selected,time:new Date().toISOString()});commit(entry?'Spending updated':'Spending saved')}catch(x){sheet.querySelector('.error').textContent=x.message}};sheet.querySelector('#amount').focus()}
function categoryEditor(cat){let color=cat?.color||palette[0];modal(cat?'Edit category':'New category',`<form><label for="name">Category name</label><input id="name" maxlength="40" required value="${esc(cat?.name||'')}"><div class="two"><div><label for="emoji">Emoji</label><input id="emoji" maxlength="16" aria-describedby="emoji-help" value="${esc(cat?.emoji||'✨')}"></div><div><label for="budget">Budget in euros</label><input id="budget" inputmode="decimal" required value="${cat?(cat.budget/100).toFixed(2):''}" placeholder="0.00"></div></div><p id="emoji-help" class="muted">Tap an icon below, or paste your own. Blank uses ✨.</p><div class="emoji-picker" aria-label="Category icons">${[['🛒','Groceries'],['🚌','Transport'],['🍻','Social'],['🛍️','Shopping'],['☕','Coffee'],['🍽️','Eating out'],['🏠','Home'],['💡','Bills'],['🎟️','Entertainment'],['💊','Health'],['🎁','Gifts'],['✨','Other']].map(([emoji,name])=>`<button type="button" class="emoji-option" data-emoji="${emoji}" aria-label="${name} icon">${emoji}</button>`).join('')}</div><label>Category colour</label><div class="palette">${palette.map((p,i)=>`<button type="button" class="swatch ${p===color?'selected':''}" style="--accent:${p}" data-color="${p}" aria-label="${['Olive','Terracotta','Blue','Plum','Gold','Teal'][i]}" aria-pressed="${p===color}"></button>`).join('')}</div><div class="error" role="alert"></div><button class="save">Save category</button></form>`);sheet.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{sheet.querySelector('#emoji').value=b.dataset.emoji});sheet.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;sheet.querySelectorAll('[data-emoji]').forEach(b=>b.onclick=()=>{sheet.querySelector('#emoji').value=b.dataset.emoji});sheet.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})});sheet.querySelector('form').onsubmit=e=>{e.preventDefault();try{const name=sheet.querySelector('#name').value.trim(),emoji=sheet.querySelector('#emoji').value.trim()||'✨',budget=amountCents(sheet.querySelector('#budget').value);if(!name||!emoji)throw Error('Enter a name and emoji.');if(cat)Object.assign(cat,{name,emoji,budget,color});else state.categories.push({id:id(),name,emoji,budget,color,archived:false});commit('Category saved')}catch(x){sheet.querySelector('.error').textContent=x.message}}}
function confirmAction(title,text,callback){modal(title,`<p class="muted">${text}</p><button class="save" id="confirm">Confirm</button>`);sheet.querySelector('#confirm').onclick=callback}
function action(a,key){const cat=state.categories.find(c=>c.id===key),entry=state.entries.find(e=>e.id===key);if(a==='add')expense();if(a==='editentry')expense(entry);if(a==='new')categoryEditor();if(a==='editcat')categoryEditor(cat);if(a==='history'||a==='category'){view='history';filter=a==='category'?key:null;render()}if(a==='delete')confirmAction('Delete spending?',`Remove this ${euro(entry.amount)} entry from your current cycle?`,()=>{state.entries=state.entries.filter(e=>e.id!==key);commit('Spending deleted')});if(a==='archive')confirmAction('Archive '+esc(cat.name)+'?', 'This category and its spending will be excluded from the active budget. You can restore it anytime.',()=>{cat.archived=true;commit('Category archived')});if(a==='restore'){cat.archived=false;commit('Category restored')}if(a==='up'||a==='down'){const idx=state.categories.indexOf(cat),other=idx+(a==='up'?-1:1);if(other>=0&&other<state.categories.length){[state.categories[idx],state.categories[other]]=[state.categories[other],state.categories[idx]];persist();render()}}}
let lastDay=dateKey(new Date());function refreshDay(){const today=dateKey(new Date());if(today!==lastDay){lastDay=today;rollover(state);persist();if(sheet.open)sheet.close();render()}}
setInterval(refreshDay,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDay()});window.addEventListener('focus',refreshDay);window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=rollover(JSON.parse(e.newValue));if(sheet.open)sheet.close();render()}catch{toast('Could not read changes from another tab.')}}});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup unavailable. You can still use the app online.'));
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_current_budget',title:'Read current budget',description:'Read the current cycle dates and active category allowances from this device-local budget.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No parameters accepted');refreshDay();const c=cycle();return {cycle:c,total:summary(c),categories:active().map(cat=>({name:cat.name,...metrics(cat.budget,spentFor(state,cat.id),c)})),amountUnit:'euro cents'}}})).catch(()=>{})}catch{}}
